        // -- The accountless screen ----------------------------------------
        //
        // Ported from the console's `pub.*` rows rather than translated
        // again: one product says one thing, and a second translation of the
        // same sentence is a second thing to keep in step. The four keys the
        // console has no row for name UI only a shell has — a sheet's dismiss
        // button, two client-side validation lines and a placeholder.
        "pub.sub": ["en": "Without an account", "es": "Sin cuenta", "fr": "Sans compte", "de": "Ohne Konto", "pt": "Sem conta", "it": "Senza account", "ja": "アカウントなしで", "zh": "无需账户", "hi": "बिना खाते के", "ar": "بدون حساب"],
        "pub.invite": ["en": "Here about a profile, not for one?", "es": "¿Viene por un perfil, no a crear uno?", "fr": "Ici à propos d'un profil, pas pour en créer un ?", "de": "Wegen eines Profils hier, nicht für eines?", "pt": "Está aqui por causa de um perfil, não para criar um?", "it": "Sei qui per un profilo, non per crearne uno?", "ja": "プロフィールを作りに来たのではなく、あるプロフィールの件でしょうか？", "zh": "你是为某个资料而来，而不是来创建一个？", "hi": "किसी प्रोफ़ाइल के बारे में आए हैं, बनाने नहीं?", "ar": "أتيت بشأن ملف، لا لإنشاء واحد؟"],
        "pub.invite.none": ["en": "Neither needs an account.", "es": "Ninguna de las dos necesita cuenta.", "fr": "Aucun des deux ne nécessite de compte.", "de": "Für beides ist kein Konto nötig.", "pt": "Nenhuma das duas precisa de conta.", "it": "Nessuna delle due richiede un account.", "ja": "どちらもアカウントは不要です。", "zh": "两者都不需要账户。", "hi": "दोनों के लिए खाता ज़रूरी नहीं।", "ar": "لا يحتاج أيٌّ منهما إلى حساب."],
        "pub.object.title": ["en": "A profile depicts me", "es": "Un perfil me representa", "fr": "Un profil me représente", "de": "Ein Profil stellt mich dar", "pt": "Um perfil representa-me", "it": "Un profilo mi rappresenta", "ja": "私を模したプロフィールがあります", "zh": "有一个资料在描绘我", "hi": "एक प्रोफ़ाइल मुझे दर्शाती है", "ar": "هناك ملف يصوّرني"],
        "pub.tab.mark": ["en": "Is this genuine?", "es": "¿Esto es auténtico?", "fr": "Est-ce authentique ?", "de": "Ist das echt?", "pt": "Isto é genuíno?", "it": "È autentico?", "ja": "これは本物ですか？", "zh": "这是真的吗？", "hi": "क्या यह असली है?", "ar": "هل هذا أصلي؟"],
        "pub.object.restricts": ["en": "You do not need an account, and this page is the proof of it rather than a promise about it. Opening an objection restricts the profile straight away — public surfaces off, no new interactors — before anybody reviews it.", "es": "No necesita una cuenta, y esta página es la prueba de ello, no una promesa al respecto. Abrir una objeción restringe el perfil de inmediato —superficies públicas desactivadas, sin nuevos interlocutores— antes de que nadie lo revise.", "fr": "Vous n'avez pas besoin de compte, et cette page en est la preuve plutôt qu'une promesse. Ouvrir une contestation restreint le profil immédiatement — surfaces publiques coupées, aucun nouvel interlocuteur — avant tout examen.", "de": "Sie brauchen kein Konto, und diese Seite ist der Beweis dafür statt eines Versprechens darüber. Ein Widerspruch beschränkt das Profil sofort — öffentliche Flächen aus, keine neuen Gesprächspartner — noch bevor jemand es prüft.", "pt": "Não precisa de conta, e esta página é a prova disso e não uma promessa sobre isso. Abrir uma contestação restringe o perfil de imediato — superfícies públicas desligadas, sem novos interlocutores — antes de alguém a analisar.", "it": "Non serve un account, e questa pagina ne è la prova anziché una promessa. Aprire una contestazione limita subito il profilo — superfici pubbliche spente, nessun nuovo interlocutore — prima che qualcuno la esamini.", "ja": "アカウントは不要です。このページはその約束ではなく、その証拠です。異議を申し立てると、誰かが審査する前に、プロフィールは直ちに制限されます（公開面は停止、新しい相手とのやり取りも停止）。", "zh": "你不需要账户，本页面就是证明，而不是关于它的承诺。提出异议会立即限制该资料 — 关闭公开界面、不再接受新的互动对象 — 在任何人审核之前。", "hi": "आपको खाते की ज़रूरत नहीं, और यह पृष्ठ उसका वादा नहीं बल्कि प्रमाण है। आपत्ति दर्ज करते ही प्रोफ़ाइल तुरंत सीमित हो जाती है — सार्वजनिक सतहें बंद, कोई नया संवादकर्ता नहीं — किसी की समीक्षा से पहले।", "ar": "لا تحتاج إلى حساب، وهذه الصفحة هي الدليل على ذلك لا وعدًا به. فتح اعتراض يقيّد الملف فورًا — إيقاف الواجهات العامة، ولا متفاعلين جدد — قبل أن يراجعه أحد."],
        "pub.object.profileId": ["en": "the profile's id", "es": "el id del perfil", "fr": "l'identifiant du profil", "de": "die ID des Profils", "pt": "o id do perfil", "it": "l'id del profilo", "ja": "プロフィールのID", "zh": "该资料的 id", "hi": "प्रोफ़ाइल की आईडी", "ar": "معرّف الملف"],
        "pub.object.ref": ["en": "your proof reference", "es": "su referencia de prueba", "fr": "votre référence de preuve", "de": "Ihr Nachweis-Aktenzeichen", "pt": "a sua referência de prova", "it": "il tuo riferimento di prova", "ja": "本人確認の参照番号", "zh": "你的证明编号", "hi": "आपका प्रमाण संदर्भ", "ar": "مرجع إثباتك"],
        "pub.object.reason": ["en": "why — in your own words", "es": "por qué — con sus palabras", "fr": "pourquoi — avec vos mots", "de": "warum — in Ihren eigenen Worten", "pt": "porquê — nas suas palavras", "it": "perché — con parole tue", "ja": "理由 — ご自身の言葉で", "zh": "原因 — 用你自己的话", "hi": "क्यों — अपने शब्दों में", "ar": "لماذا — بكلماتك"],
        "pub.object.ref.note": ["en": "The proof reference points at an identity check held outside this system — it is not a login, and it is what lets you object without one.", "es": "La referencia de prueba apunta a una comprobación de identidad realizada fuera de este sistema: no es un inicio de sesión, y es lo que le permite objetar sin tener uno.", "fr": "La référence de preuve renvoie à une vérification d'identité effectuée hors de ce système : ce n'est pas une connexion, et c'est ce qui vous permet de contester sans en avoir une.", "de": "Das Nachweis-Aktenzeichen verweist auf eine Identitätsprüfung außerhalb dieses Systems — es ist keine Anmeldung, und genau deshalb können Sie ohne eine widersprechen.", "pt": "A referência de prova aponta para uma verificação de identidade feita fora deste sistema: não é um início de sessão, e é o que lhe permite contestar sem ter um.", "it": "Il riferimento di prova rimanda a una verifica d'identità tenuta fuori da questo sistema: non è un accesso, ed è ciò che ti permette di contestare senza averne uno.", "ja": "参照番号は、この仕組みの外で行われた本人確認を指します。ログインではなく、ログインなしで異議を申し立てられるようにするためのものです。", "zh": "证明编号指向在本系统之外完成的身份核验 — 它不是登录凭据，正是它让你无需登录也能提出异议。", "hi": "प्रमाण संदर्भ इस प्रणाली के बाहर हुई पहचान-जाँच की ओर इशारा करता है — यह लॉगिन नहीं है, और यही आपको बिना लॉगिन के आपत्ति दर्ज करने देता है।", "ar": "مرجع الإثبات يشير إلى تحقّق من الهوية جرى خارج هذا النظام — ليس تسجيل دخول، وهو ما يتيح لك الاعتراض بدونه."],
        "pub.object.open": ["en": "Open it", "es": "Abrirla", "fr": "L'ouvrir", "de": "Einreichen", "pt": "Abrir", "it": "Aprila", "ja": "申し立てる", "zh": "提出", "hi": "दर्ज करें", "ar": "افتحه"],
        "pub.object.opened": ["en": "Opened — {id}", "es": "Abierta — {id}", "fr": "Ouverte — {id}", "de": "Eröffnet — {id}", "pt": "Aberta — {id}", "it": "Aperta — {id}", "ja": "受付済み — {id}", "zh": "已提出 — {id}", "hi": "दर्ज — {id}", "ar": "فُتح — {id}"],
        "pub.object.opened.status": ["en": "The profile is {now} from this moment. It was {before}, and if the objection is dismissed it goes back to exactly that.", "es": "El perfil queda {now} desde este momento. Era {before}, y si la objeción se desestima vuelve exactamente a eso.", "fr": "Le profil est {now} à partir de maintenant. Il était {before}, et si la contestation est rejetée il y revient exactement.", "de": "Das Profil ist ab sofort {now}. Es war {before}, und wenn der Widerspruch abgewiesen wird, kehrt es genau dorthin zurück.", "pt": "O perfil fica {now} a partir deste momento. Era {before}, e se a contestação for rejeitada volta exatamente a isso.", "it": "Il profilo è {now} da questo momento. Era {before}, e se la contestazione viene respinta torna esattamente a quello.", "ja": "プロフィールはこの時点から {now} になります。それまでは {before} でした。異議が棄却されれば、そのままの状態に戻ります。", "zh": "该资料从此刻起为 {now}。此前是 {before}；若异议被驳回，将完全恢复原状。", "hi": "इस क्षण से प्रोफ़ाइल {now} है। यह {before} थी, और यदि आपत्ति खारिज होती है तो वह ठीक वैसी ही हो जाएगी।", "ar": "الملف {now} اعتبارًا من هذه اللحظة. كان {before}، وإذا رُفض الاعتراض عاد إلى ذلك تمامًا."],
        "pub.object.writeitdown": ["en": "Write the id down. It is how you check this case later without an account — there is no inbox here to come back to.", "es": "Anote el identificador. Es cómo consultará este caso más adelante sin una cuenta: aquí no hay bandeja de entrada a la que volver.", "fr": "Notez l'identifiant. C'est ainsi que vous suivrez ce dossier plus tard sans compte : il n'y a pas de boîte de réception ici où revenir.", "de": "Notieren Sie die ID. So prüfen Sie diesen Fall später ohne Konto — hier gibt es keinen Posteingang, zu dem Sie zurückkehren könnten.", "pt": "Anote o id. É assim que consultará este caso mais tarde sem conta — aqui não há caixa de entrada para onde voltar.", "it": "Annota l'id. È così che controllerai questo caso più avanti senza un account: qui non c'è una casella a cui tornare.", "ja": "IDを控えてください。アカウントなしで後からこの件を確認する唯一の方法です。戻ってこられる受信箱はありません。", "zh": "请记下这个 id。这是你日后在没有账户的情况下查询本案的方式 — 这里没有可供你回来查看的收件箱。", "hi": "यह आईडी लिख लें। बिना खाते के बाद में इस मामले को देखने का यही तरीका है — यहाँ लौटने के लिए कोई इनबॉक्स नहीं है।", "ar": "دوّن المعرّف. فهو كيف تتابع هذه القضية لاحقًا بدون حساب — لا يوجد هنا صندوق وارد تعود إليه."],
        "pub.mark.title": ["en": "Somebody sent me this", "es": "Alguien me envió esto", "fr": "Quelqu'un m'a envoyé ceci", "de": "Jemand hat mir das geschickt", "pt": "Alguém enviou-me isto", "it": "Qualcuno mi ha mandato questo", "ja": "これを送られてきました", "zh": "有人给我发了这个", "hi": "किसी ने मुझे यह भेजा", "ar": "أرسل لي أحدهم هذا"],
        "pub.mark.explain": ["en": "Paste it. This asks whose work it is with no credential id, and keeps answering after the text has been reworded — which is the state text usually arrives in. It is the right question for a stranger holding a screenshot; checking a credential you already hold is a different one and lives inside an account.", "es": "Péguelo. Esto pregunta de quién es el trabajo sin ningún identificador de credencial, y sigue respondiendo después de que el texto haya sido reescrito, que es el estado en el que suele llegar. Es la pregunta correcta para un desconocido con una captura de pantalla; comprobar una credencial que ya tiene es otra distinta y vive dentro de una cuenta.", "fr": "Collez-le. Ceci demande à qui appartient le contenu sans aucun identifiant de justificatif, et répond encore après reformulation du texte — l'état dans lequel il arrive le plus souvent. C'est la bonne question pour un inconnu tenant une capture d'écran ; vérifier un justificatif que vous détenez déjà en est une autre, et elle vit dans un compte.", "de": "Fügen Sie ihn ein. Das fragt, wessen Werk es ist, ohne jede Credential-ID, und antwortet auch noch, nachdem der Text umformuliert wurde — der Zustand, in dem Text meist ankommt. Es ist die richtige Frage für eine fremde Person mit einem Screenshot; ein Nachweis, den Sie bereits halten, ist eine andere Frage und lebt in einem Konto.", "pt": "Cole-o. Isto pergunta de quem é o trabalho sem qualquer identificador de credencial, e continua respondendo depois de o texto ter sido reescrito — o estado em que o texto costuma chegar. É a pergunta certa para um desconhecido com uma captura de tela; verificar uma credencial que você já possui é outra e vive dentro de uma conta.", "it": "Incollalo. Questo chiede di chi è il lavoro senza alcun identificativo di credenziale, e continua a rispondere dopo che il testo è stato riformulato — lo stato in cui il testo di solito arriva. È la domanda giusta per uno sconosciuto con uno screenshot; verificare una credenziale che già possiedi è un'altra cosa e vive dentro un account.", "ja": "貼り付けてください。これは資格情報の ID なしに、それが誰の作かを尋ねます。文章が書き換えられた後でも答え続けます — 実際に届く文章はたいていその状態です。スクリーンショットを手にした見知らぬ人にとって正しい問いです。すでに持っている資格情報を確認するのは別の問いで、それはアカウントの中にあります。", "zh": "粘贴进来。这会在不需要任何凭据 ID 的情况下询问它出自谁手，并且在文本被改写之后仍能作答 — 而文本通常正是以这种状态出现的。对于手持截图的陌生人，这是正确的问题；核验你已经持有的凭据是另一个问题，它属于账户内部。", "hi": "इसे चिपकाएँ। यह बिना किसी क्रेडेंशियल आईडी के पूछता है कि यह किसका काम है, और पाठ के शब्द बदल दिए जाने के बाद भी उत्तर देता रहता है — पाठ आम तौर पर इसी हालत में पहुँचता है। स्क्रीनशॉट थामे किसी अजनबी के लिए यही सही सवाल है; जो क्रेडेंशियल आपके पास पहले से है उसे जाँचना अलग सवाल है और वह खाते के भीतर रहता है।", "ar": "الصقه هنا. هذا يسأل عن صاحب العمل دون أي معرّف اعتماد، ويظل يجيب بعد إعادة صياغة النص — وهي الحالة التي يصل بها النص عادةً. إنه السؤال الصحيح لغريب يحمل لقطة شاشة؛ أما التحقق من اعتماد تملكه بالفعل فسؤال آخر يعيش داخل حساب."],
        "pub.mark.paste": ["en": "paste the text", "es": "pegue el texto", "fr": "collez le texte", "de": "Text einfügen", "pt": "cole o texto", "it": "incolla il testo", "ja": "テキストを貼り付けてください", "zh": "粘贴文本", "hi": "पाठ चिपकाएँ", "ar": "الصق النص"],
        "pub.mark.ask": ["en": "Ask who wrote it", "es": "Preguntar quién lo escribió", "fr": "Demander qui l'a écrit", "de": "Fragen, wer es geschrieben hat", "pt": "Perguntar quem o escreveu", "it": "Chiedi chi l'ha scritto", "ja": "誰が書いたか調べる", "zh": "查询是谁写的", "hi": "पूछें किसने लिखा", "ar": "اسأل من كتبه"],
        "pub.mark.producedby": ["en": "Produced by a QRME synthetic profile — {state}.", "es": "Producido por un perfil sintético de QRME — {state}.", "fr": "Produit par un profil synthétique QRME — {state}.", "de": "Erzeugt von einem synthetischen QRME-Profil — {state}.", "pt": "Produzido por um perfil sintético do QRME — {state}.", "it": "Prodotto da un profilo sintetico QRME — {state}.", "ja": "QRME の合成プロフィールによる生成物 — {state}。", "zh": "由 QRME 合成资料生成 — {state}。", "hi": "QRME की सिंथेटिक प्रोफ़ाइल द्वारा निर्मित — {state}।", "ar": "من إنتاج ملف اصطناعي في QRME — {state}."],
        "pub.mark.windows": ["en": "{matched} of {stored} stored windows matched, out of {examined} examined (similarity {similarity}).", "es": "Coincidieron {matched} de {stored} ventanas almacenadas, de {examined} examinadas (similitud {similarity}).", "fr": "{matched} fenêtres enregistrées sur {stored} correspondent, sur {examined} examinées (similarité {similarity}).", "de": "{matched} von {stored} gespeicherten Fenstern stimmten überein, bei {examined} geprüften (Ähnlichkeit {similarity}).", "pt": "Coincidiram {matched} de {stored} janelas armazenadas, entre {examined} examinadas (similaridade {similarity}).", "it": "Hanno corrisposto {matched} finestre su {stored} memorizzate, su {examined} esaminate (somiglianza {similarity}).", "ja": "保存済み {stored} 個のウィンドウのうち {matched} 個が一致しました（検査対象 {examined} 個、類似度 {similarity}）。", "zh": "在 {examined} 个受检窗口中，已存储的 {stored} 个窗口有 {matched} 个匹配（相似度 {similarity}）。", "hi": "संग्रहीत {stored} विंडो में से {matched} मेल खाईं, कुल {examined} जाँची गईं (समानता {similarity})।", "ar": "تطابقت {matched} من أصل {stored} نافذة مخزّنة، من بين {examined} جرى فحصها (التشابه {similarity})."],
        "pub.mark.altered": ["en": "The wording has changed since it was stamped. That does not make it less traceable — it is what the score above is measuring.", "es": "La redacción ha cambiado desde que se selló. Eso no lo hace menos rastreable: es precisamente lo que mide la puntuación anterior.", "fr": "La formulation a changé depuis l'horodatage. Cela ne le rend pas moins traçable : c'est justement ce que mesure le score ci-dessus.", "de": "Der Wortlaut hat sich seit der Kennzeichnung geändert. Das macht ihn nicht weniger nachverfolgbar — genau das misst der Wert oben.", "pt": "A redação mudou desde que foi selada. Isso não a torna menos rastreável: é precisamente o que a pontuação acima mede.", "it": "Il testo è cambiato da quando è stato marcato. Questo non lo rende meno tracciabile: è proprio ciò che il punteggio sopra misura.", "ja": "刻印されてから文言が変わっています。それで追跡できなくなるわけではありません。上のスコアが測っているのはまさにその差です。", "zh": "自加盖标记以来措辞已经改变。这并不会让它更难追溯 — 上面的分数衡量的正是这一点。", "hi": "मुहर लगने के बाद शब्द बदले हैं। इससे यह कम पता लगाने योग्य नहीं होता — ऊपर का स्कोर यही माप रहा है।", "ar": "تغيّرت الصياغة منذ ختمه. هذا لا يجعله أقل قابلية للتتبّع — فذلك تحديدًا ما تقيسه الدرجة أعلاه."],
        "pub.mark.unknown": ["en": "Not recognised", "es": "No reconocido", "fr": "Non reconnu", "de": "Nicht erkannt", "pt": "Não reconhecido", "it": "Non riconosciuto", "ja": "該当なし", "zh": "未识别", "hi": "पहचाना नहीं गया", "ar": "غير معروف"],
        "pub.mark.unknown.explain": ["en": "This says nothing about whether a person wrote it. It says no profile {here} has stamped work that shares enough wording with it.", "es": "Esto no dice nada sobre si lo escribió una persona. Dice que ningún perfil {here} ha firmado un trabajo que comparta suficiente redacción con él.", "fr": "Cela ne dit rien sur le fait qu'une personne l'ait écrit. Cela dit qu'aucun profil {here} n'a signé un contenu partageant assez de formulations avec lui.", "de": "Das sagt nichts darüber, ob ein Mensch es geschrieben hat. Es sagt, dass kein Profil {here} eine Arbeit gestempelt hat, die genug Wortlaut mit ihr teilt.", "pt": "Isto não diz nada sobre se uma pessoa o escreveu. Diz que nenhum perfil {here} carimbou um trabalho que partilhe redação suficiente com ele.", "it": "Questo non dice nulla sul fatto che l'abbia scritto una persona. Dice che nessun profilo {here} ha timbrato un lavoro che condivida abbastanza formulazioni con esso.", "ja": "これは人が書いたかどうかについては何も述べていません。{here}、これと十分に語句を共有する作品に印を付けたプロフィールが存在しない、という意味です。", "zh": "这并不说明它是否由人所写。它说明的是：{here}没有任何资料曾为与之用词足够相近的作品加过标记。", "hi": "इससे यह पता नहीं चलता कि इसे किसी व्यक्ति ने लिखा या नहीं। इसका अर्थ है कि {here} किसी प्रोफ़ाइल ने ऐसा काम मुहरबंद नहीं किया जिसकी शब्दावली इससे पर्याप्त मेल खाती हो।", "ar": "هذا لا يقول شيئًا عمّا إذا كان قد كتبه إنسان. إنه يقول إنه ما من ملف {here} ختم عملًا يشترك معه في ما يكفي من الصياغة."],
        "pub.mark.here": ["en": "on this deployment", "es": "en esta instalación", "fr": "sur ce déploiement", "de": "auf dieser Installation", "pt": "nesta instalação", "it": "su questa installazione", "ja": "この環境で", "zh": "在本部署中", "hi": "इस परिनियोजन पर", "ar": "في هذا التنصيب"],
        "pub.notoken": ["en": "Nothing on this page reads or needs a token.", "es": "Nada en esta página lee ni necesita una credencial.", "fr": "Rien sur cette page ne lit ni ne requiert d'identifiant.", "de": "Nichts auf dieser Seite liest oder braucht ein Token.", "pt": "Nada nesta página lê ou precisa de uma credencial.", "it": "Nulla in questa pagina legge o richiede una credenziale.", "ja": "このページは資格情報を読み取らず、必要ともしません。", "zh": "本页面既不读取也不需要任何凭据。", "hi": "इस पृष्ठ पर कुछ भी टोकन नहीं पढ़ता और न ही चाहिए।", "ar": "لا شيء في هذه الصفحة يقرأ رمزًا أو يحتاج إليه."],
        "pub.state.active": ["en": "active", "es": "activo", "fr": "actif", "de": "aktiv", "pt": "ativo", "it": "attivo", "ja": "有効", "zh": "有效", "hi": "सक्रिय", "ar": "نشط"],
        "pub.state.restricted": ["en": "restricted", "es": "restringido", "fr": "restreint", "de": "beschränkt", "pt": "restringido", "it": "limitato", "ja": "制限中", "zh": "受限", "hi": "सीमित", "ar": "مقيَّد"],
        "pub.state.departed": ["en": "departed", "es": "fallecido", "fr": "disparu", "de": "verstorben", "pt": "falecido", "it": "scomparso", "ja": "故人", "zh": "已故", "hi": "दिवंगत", "ar": "متوفى"],
        "pub.state.terminated": ["en": "terminated", "es": "terminado", "fr": "supprimé", "de": "beendet", "pt": "terminado", "it": "terminato", "ja": "終了", "zh": "已终止", "hi": "समाप्त", "ar": "مُنهى"],
        "pub.back.short": ["en": "Back", "es": "Atrás", "fr": "Retour", "de": "Zurück", "pt": "Voltar", "it": "Indietro", "ja": "戻る", "zh": "返回", "hi": "वापस", "ar": "رجوع"],
        "pub.object.needid": ["en": "Enter the profile's id and your proof reference.", "es": "Introduzca el id del perfil y su referencia de prueba.", "fr": "Saisissez l'identifiant du profil et votre référence de preuve.", "de": "Geben Sie die Profil-ID und Ihre Nachweisreferenz ein.", "pt": "Introduza o id do perfil e a sua referência de prova.", "it": "Inserisci l'id del profilo e il tuo riferimento di prova.", "ja": "プロフィールIDと証明の参照番号を入力してください。", "zh": "请输入资料 id 和你的证明参考号。", "hi": "प्रोफ़ाइल आईडी और अपना प्रमाण संदर्भ दर्ज करें।", "ar": "أدخل معرّف الملف ومرجع إثباتك."],
        "pub.mark.needtext": ["en": "Paste the text first.", "es": "Pegue primero el texto.", "fr": "Collez d'abord le texte.", "de": "Fügen Sie zuerst den Text ein.", "pt": "Cole primeiro o texto.", "it": "Incolla prima il testo.", "ja": "先にテキストを貼り付けてください。", "zh": "请先粘贴文本。", "hi": "पहले पाठ चिपकाएँ।", "ar": "الصق النص أولاً."],
        "pub.object.ref.ph": ["en": "an identity check held elsewhere", "es": "una verificación de identidad hecha en otro sitio", "fr": "une vérification d'identité conservée ailleurs", "de": "eine anderswo geführte Identitätsprüfung", "pt": "uma verificação de identidade guardada noutro lado", "it": "una verifica d'identità conservata altrove", "ja": "他所で行われた本人確認", "zh": "在别处完成的身份验证", "hi": "कहीं और रखी गई पहचान जाँच", "ar": "تحقّق من الهوية محفوظ في مكان آخر"],
